{
  "name": "实验室离心机",
  "name_en": "Laboratory Centrifuge",
  "manufacturer": "",
  "description": "实验室离心机利用离心力分离液体样品中的不同组分，常用于样品沉降、相分离和前处理。该设备具备舱门控制、转篮/吊篮位置切换，以及按设定离心力和时间执行离心循环的能力，可用于自动化样品处理流程。",
  "description_en": "A laboratory centrifuge uses centrifugal force to separate components in liquid samples. It is commonly used for pelleting, phase separation, and sample preparation. This device supports door control, indexed bucket positions, and timed spin cycles at a specified g-force, making it suitable for automated sample-handling workflows.",
  "tag_hints": [
    "centrifugation",
    "sample separation",
    "g-force control",
    "timed spin cycle",
    "swing-bucket rotor",
    "door interlock",
    "automated sample loading"
  ],
  "actions": [
    {
      "action_name": "auto-open_door",
      "description": "打开离心机门。",
      "description_en": "Open the centrifuge door."
    },
    {
      "action_name": "auto-close_door",
      "description": "关闭离心机门。",
      "description_en": "Close the centrifuge door."
    },
    {
      "action_name": "auto-door_open",
      "description": "获取离心机门是否打开。",
      "description_en": "Get whether the centrifuge door is open."
    },
    {
      "action_name": "auto-lock_door",
      "description": "锁定离心机门。",
      "description_en": "Lock the centrifuge door."
    },
    {
      "action_name": "auto-unlock_door",
      "description": "解锁离心机门。",
      "description_en": "Unlock the centrifuge door."
    },
    {
      "action_name": "auto-unlock_bucket",
      "description": "解锁转篮/吊篮。",
      "description_en": "Unlock the bucket."
    },
    {
      "action_name": "auto-lock_bucket",
      "description": "锁定转篮/吊篮。",
      "description_en": "Lock the bucket."
    },
    {
      "action_name": "auto-go_to_bucket1",
      "description": "将转子定位到 1 号转篮/吊篮位置。",
      "description_en": "Index the rotor to bucket position 1."
    },
    {
      "action_name": "auto-go_to_bucket2",
      "description": "将转子定位到 2 号转篮/吊篮位置。",
      "description_en": "Index the rotor to bucket position 2."
    },
    {
      "action_name": "auto-start_spin_cycle",
      "description": "按设定离心力和持续时间启动一次离心循环。",
      "description_en": "Start a spin cycle at the specified g-force for the specified duration."
    },
    {
      "action_name": "auto-spin",
      "description": "按设定离心力和持续时间执行离心。",
      "description_en": "Run the centrifuge at the specified g-force for the specified duration."
    },
    {
      "action_name": "auto-at_bucket",
      "description": "获取当前位于操作位置的转篮/吊篮。",
      "description_en": "Get which bucket is currently at the access position."
    },
    {
      "action_name": "auto-serialize",
      "description": "导出设备的序列化信息。",
      "description_en": "Serialize the device representation."
    },
    {
      "action_name": "auto-deserialize",
      "description": "从序列化信息恢复设备表示。",
      "description_en": "Reconstruct the device representation from serialized data."
    },
    {
      "action_name": "auto-load",
      "description": "将样品装入离心机。",
      "description_en": "Load a sample into the centrifuge."
    },
    {
      "action_name": "auto-unload",
      "description": "将样品从离心机中取出。",
      "description_en": "Unload a sample from the centrifuge."
    }
  ]
}

